3	import java.util.Objects;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.escalation.OwnerAlreadyExistsException;
9	
10	/**
11	 * Rejects creating an owner whose telephone number is already used by any other
12	 * owner with a 409 conflict. Matching ignores letter case and surrounding or
13	 * repeated whitespace (see {@link DuplicateKey}).
14	 */
15	public class EnsureOwnerUnique {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
18	            throws OwnerAlreadyExistsException {
19	        String telephoneKey = DuplicateKey.of(owner.getTelephone());
20	        if (telephoneKey == null) {
21	            return;
22	        }
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (Objects.equals(DuplicateKey.of(existing.getTelephone()), telephoneKey)) {
25	                throw new OwnerAlreadyExistsException(
26	                        "Owner with telephone " + owner.getTelephone() + " already exists");
27	            }
28	        }
29	    }
30	}
