10	/**
11	 * When an email address is provided, rejects creating an owner whose email is
12	 * already used by another owner with a 409 conflict. Owners without an email are
13	 * unaffected. Matching ignores letter case and surrounding or repeated whitespace
14	 * (see {@link DuplicateKey}).
15	 */
16	public class EnsureOwnerEmailUnique {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
19	            throws OwnerAlreadyExistsException {
20	        String email = owner.getEmail();
21	        String emailKey = DuplicateKey.of(email);
22	        if (emailKey == null) {
23	            return;
24	        }
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (Objects.equals(DuplicateKey.of(existing.getEmail()), emailKey)) {
27	                throw new OwnerAlreadyExistsException(
28	                        "Owner with email " + email + " already exists");
29	            }
30	        }
31	    }
32	}
