1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	/**
6	 * Normalises a value for duplicate detection so that comparisons ignore letter
7	 * case and surrounding or repeated whitespace. Thus {@code "  john   smith "}
8	 * and {@code "John Smith"} normalise to the same key and count as duplicates.
9	 */
10	final class DuplicateKey {
11	
12	    private DuplicateKey() {
13	    }
14	
15	    /**
16	     * @return a case- and whitespace-insensitive key for {@code value}, or
17	     *         {@code null} when {@code value} is {@code null} or blank.
18	     */
19	    static String of(String value) {
20	        if (value == null) {
21	            return null;
22	        }
23	        String collapsed = value.trim().replaceAll("\\s+", " ");
24	        if (collapsed.isEmpty()) {
25	            return null;
26	        }
27	        return collapsed.toLowerCase(Locale.ROOT);
28	    }
29	}
